import{_ as n,l as o,o as a,c as t,v as r,p as l,x as E,d as s,i as p,S as B}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"完美贝叶斯与信号精炼","description":"","frontmatter":{"title":"完美贝叶斯与信号精炼","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/perfect-bayesian.md","filePath":"econ/perfect-bayesian.md","lastUpdated":1789023840000}'),d={name:"econ/perfect-bayesian.md"};function c(m,e,h,u,A,P){const i=o("Mermaid");return a(),t("div",null,[e[1]||(e[1]=r('<h1 id="完美贝叶斯与信号精炼" tabindex="-1">完美贝叶斯与信号精炼 <a class="header-anchor" href="#完美贝叶斯与信号精炼" aria-label="Permalink to &quot;完美贝叶斯与信号精炼&quot;">​</a></h1><div class="epigraph"><p>均衡必须在每个信息集上给出信念，策略在该信念下最优，信念在路径上由贝叶斯法则更新。</p><footer>—— 据 Kreps and Wilson, Sequential Equilibria, Econometrica, 1982；Fudenberg and Tirole, JET, 1991 整理</footer></div><p><a href="/econ/bayesian-nash">上一课</a>（不完全信息与贝叶斯纳什）。的 BNE 把类型写进策略，但不约束零概率信息集。信号博弈里，接收者看见一个「不该出现」的行动，后验随便写，可以撑住「我若偏离你就当成最坏类型」的恐吓。缺口是：给每个信息集配上信念，并要求策略在这些信念下序贯理性。本课钉完美贝叶斯均衡（PBE）的最低要求，并指出它仍太松，为柠檬与发送信号做准备。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扩展式加类型之后，许多信息集不是子博弈的根（信息集不是单点）。SPE 用不上。<a href="/econ/subgame-perfect">子博弈完美</a>删空威胁的那把刀，在这里不够。Kreps–Wilson 的序贯均衡用颤抖生成处处正概率，再取极限，得到策略与信念的一对 \\((\\sigma,\\mu)\\)。教科书里的 PBE 弱一点：路径上贝叶斯，路径外信念任意但策略对该信念最优。</p><p>最低两条：（1）序贯理性：在每一信息集，给定 \\(\\mu\\) 与他人策略，行动是最佳应答；（2）路径上的 \\(\\mu\\) 由 \\(\\sigma\\) 与先验经贝叶斯得到。缺（1）会回到不可信；缺（2）会让人「看见发生了的事却不更新」。</p><h3 id="pbe-仍允许很怪的路径外信念" tabindex="-1">PBE 仍允许很怪的路径外信念 <a class="header-anchor" href="#pbe-仍允许很怪的路径外信念" aria-label="Permalink to &quot;PBE 仍允许很怪的路径外信念&quot;">​</a></h3><p>偏离若是零概率，贝叶斯没有定义。接收者可以把偏离全归给高成本类型，从而吓阻发送者。Cho–Kreps 直觉标准等，用「谁更想偏离」来砍这些信念，本课只点名，不展开精炼族。柠檬与 Spence 会碰到分离、混同、以及靠怪信念撑住的混同。</p><p><span class="marginnote">信号博弈时序：自然抽类型 → 知情者发信号 → 接收者在信息集上形成 \\(\\mu\\)，选行动。分离：不同类型发不同信号，路径上信念退化到真类型。混同：信号无信息，\\(\\mu\\) 停在先验。</span></p><p>弱 PBE 允许路径外任意 \\(\\mu\\)；序贯均衡用颤抖极限把 \\(\\mu\\) 也管住。 主干后课用弱 PBE 算柠檬与 Spence，需要砍时再点直觉标准。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：有限类型、有限信号与行动的扩展式。解概念：PBE。计算常先猜分离或混同，再反推使激励相容成立的信念与行动，最后检查路径外：若某信号无人发，指定一个 \\(\\mu\\)，使无人想改发这个信号。</p><p>序贯均衡要求路径外信念也是颤抖极限，比任意 PBE 紧。主干后课用 PBE 说话即可；需要砍均衡时再引直觉标准。</p>',13)),(a(),l(B,null,{default:E(()=>[p(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20BNE%5B%22BNE%EF%BC%9A%E4%B8%8D%E7%AE%A1%E9%9B%B6%E6%A6%82%E7%8E%87%E4%BF%A1%E6%81%AF%E9%9B%86%22%5D%20--%3E%20PBE%5B%22(%CF%83%2C%20%CE%BC)%EF%BC%9A%E5%BA%8F%E8%B4%AF%E7%90%86%E6%80%A7%20%2B%20%E8%B7%AF%E5%BE%84%E8%B4%9D%E5%8F%B6%E6%96%AF%22%5D%0A%20%20PBE%20--%3E%20SEQ%5B%22%E5%BA%8F%E8%B4%AF%E5%9D%87%E8%A1%A1%EF%BC%9A%E9%A2%A4%E6%8A%96%E6%9E%81%E9%99%90%22%5D%0A%20%20PBE%20--%3E%20LOOSE%5B%22%E8%B7%AF%E5%BE%84%E5%A4%96%20%CE%BC%20%E4%BB%8D%E8%87%AA%E7%94%B1%22%5D%0A%20%20PBE%20--%3E%20MKT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%B8%82%E5%9C%BA%E9%87%8C%E7%9A%84%E9%9A%90%E8%97%8F%E7%B1%BB%E5%9E%8B%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信念是接收者决策的状态变量。没有 \\(\\mu\\)，说「看见信号后选 \\(a\\)」没有概率论证。路径上贝叶斯保证均衡自我一致：你用来吓我的那条后验，不能与你自己的策略矛盾。路径外的自由，则是恐吓的剩余空间——精炼要砍的正是这块。</p><p>与完全信息 SPE 的连续性：若类型退化成一点，PBE 回到 SPE。不完全信息多出来的，全是信念。后课市场失灵不是新的均衡定义，而是把类型读成质量、生产率、风险，把信号读成价格、教育、合同菜单。柠檬将只用价格这一维信号；Spence 让知情者先选有成本的 \\(e\\)。两课都在 PBE 里算分离与混同，不再改解概念。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>PBE 定义在文献里不完全统一（Fudenberg–Tirole 对多期有额外「不得用无关类型的信息」等）。应用时写清：路径贝叶斯、序贯理性、以及路径外信念的限制（若有）。连续信号空间的偏离更难指定 \\(\\mu\\)。</p><p>多期信号还要求不能用「与该信息集无关的类型」去编后验，否则 PBE 的定义要按 Fudenberg–Tirole 加限制。主干后课用静态信号博弈，不踩这条。</p><p>后课默认：隐藏类型、可观察行动的互动，解是 PBE；混同与分离是候选，怪信念撑住的混同视为脆弱。</p><h3 id="先猜分离或混同-再给路径外指定信念" tabindex="-1">先猜分离或混同，再给路径外指定信念 <a class="header-anchor" href="#先猜分离或混同-再给路径外指定信念" aria-label="Permalink to &quot;先猜分离或混同，再给路径外指定信念&quot;">​</a></h3><p>算均衡时先猜分离或混同，反推激励相容，再给无人发送的信号指定 \\(\\mu\\)，使无人想改发。这不是新定义，是 PBE 的常规算法。柠檬几乎只有混同（一个价格）；Spence 两种都算。Cho–Kreps 直觉标准再砍「低类型更不想发的偏离被栽赃给低类型」的混同，本课只点名。Kreps–Wilson 序贯均衡用颤抖给路径外信念一个极限来源，比任意 PBE 紧。</p><p>多期信号还要求不能用「与该信息集无关的类型」去编后验，否则定义要按 Fudenberg–Tirole 加限制。主干后课用静态信号博弈。</p><p><span class="marginnote">接收者策略是 \\(a(m)\\)，发送者预见到 \\(a\\) 与 \\(\\mu\\)。没有成对的 \\((\\sigma,\\mu)\\)，「看见 \\(m\\) 之后选 \\(a\\)」没有概率论证。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BNE 不够；PBE 给每个信息集信念，并要求序贯理性。</li><li>路径上必须贝叶斯；路径外信念默认自由，故 PBE 仍松。</li><li>分离与混同是信号博弈的两类候选。</li><li>更强精炼（序贯、直觉标准）用来砍怪信念。</li><li>出处：Kreps and Wilson, <em>Econometrica</em> 1982；Fudenberg and Tirole, <em>JET</em> 1991。</li></ul>',13))])}const f=n(d,[["render",c]]);export{b as __pageData,f as default};
